  "487": "\n        <div id=\"binCheckoutRoot\" style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n                    background: #FFFFFF; padding: 0; border-radius: 16px; overflow: hidden; max-height: 75vh; overflow-y: auto;\">\n\n          <div style=\"background: linear-gradient(135deg, #FCD535 0%, #F0B90B 100%); padding: 18px 22px; display: flex; align-items: center; justify-content: space-between; gap: 12px;\">\n            <div style=\"display:flex;align-items:center;gap:12px;\">\n              <svg width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" fill=\"#1E2329\"><path d=\"M12 2L7.5 6.5L9.62 8.62L12 6.24L14.38 8.62L16.5 6.5L12 2ZM2 12L6.5 7.5L8.62 9.62L6.24 12L8.62 14.38L6.5 16.5L2 12ZM22 12L17.5 16.5L15.38 14.38L17.76 12L15.38 9.62L17.5 7.5L22 12ZM12 22L16.5 17.5L14.38 15.38L12 17.76L9.62 15.38L7.5 17.5L12 22ZM12 15.38L14.38 12L12 8.62L9.62 12L12 15.38Z\"/></svg>\n              <div>\n                <div style=\"font-size:18px;font-weight:800;color:#1E2329;letter-spacing:0.5px;\">Binance Pay</div>\n                <div style=\"font-size:11px;color:rgba(0,0,0,0.45);font-weight:600;\">Auto detect by Note</div>\n              </div>\n            </div>\n            <div style=\"text-align:right;\">\n              <div style=\"font-size:10px;color:rgba(0,0,0,0.5);font-weight:700;text-transform:uppercase;letter-spacing:0.5px;\">Time Left</div>\n              <div id=\"binCountdown\" style=\"font-size:16px;font-weight:900;color:#1E2329;font-variant-numeric:tabular-nums;\">",
  "488": "</div>\n            </div>\n          </div>\n\n          <div style=\"padding: 20px;\">\n\n            <div style=\"background: #FAFAFA; border: 1px solid #EAECEF; border-radius: 14px; padding: 20px; text-align: center; margin-bottom: 16px;\">\n              ",
