  "491": " <span style=\"font-size:15px;color:#707A8A;font-weight:600;\">USDT</span></p>\n              <button id=\"binCopyAmount\" style=\"margin-top:10px;background:#FFFFFF;border:1px solid #EAECEF;border-radius:8px;color:#C99400;padding:6px 16px;font-size:12px;cursor:pointer;font-weight:700;display:inline-flex;align-items:center;gap:5px;\">\n                Copy Amount\n              </button>\n            </div>\n\n            <div style=\"background:#FAFAFA;border:1px solid #EAECEF;border-radius:14px;padding:16px;margin-bottom:16px;\">\n              <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;\">\n                <span style=\"color:#707A8A;font-size:12px;font-weight:600;\">Binance Pay ID</span>\n                <div style=\"display:flex;gap:6px;align-items:center;\">\n                  <button id=\"binShowQR\" type=\"button\" style=\"position:relative;background:#FFFFFF;border:1px solid #F0B90B;border-radius:8px;color:#1E2329;padding:5px 9px;font-size:11px;cursor:pointer;font-weight:700;display:inline-flex;align-items:center;gap:4px;overflow:visible;\">\n                    <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\">\n                      <path d=\"M3 3h8v8H3V3zm2 2v4h4V5H5zm8-2h8v8h-8V3zm2 2v4h4V5h-4zM3 13h8v8H3v-8zm2 2v4h4v-4H5zm10 0h2v2h-2v-2zm4 0h2v2h-2v-2zm-4 4h2v2h-2v-2zm4 0h2v4h-4v-2h2v-2z\" fill=\"#F0B90B\"/>\n                    </svg>\n                    <span>QR</span>\n                    <span class=\"bin-qr-cursor\" aria-hidden=\"true\" style=\"display:inline-flex;\">\n                      <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\">\n                        <path d=\"M5.5 3.2l13.2 7.1c.7.4.4 1.4-.4 1.4h-5.3l-2.4 6.8c-.2.7-1.3.7-1.5 0L5.5 3.2z\" fill=\"#707A8A\"/>\n                      </svg>\n                    </span>\n                  </button>\n                  <button id=\"binCopyUid\" style=\"background:#F0B90B;border:none;border-radius:8px;color:#1E2329;padding:5px 14px;font-size:11px;cursor:pointer;font-weight:800;\">Copy ID</button>\n                </div>\n              </div>\n              <p style=\"color:#1E2329;font-size:22px;font-weight:800;letter-spacing:2px;margin:0;word-break:break-all;\">",
  "492": "</p>\n              ",
  "493": "\n            </div>\n\n            <div style=\"background:#FFF7E6;border:2px solid #F0B90B;border-radius:14px;padding:16px;margin-bottom:16px;text-align:center;\">\n              <p style=\"color:#C99400;font-size:12px;font-weight:800;margin:0 0 8px;text-transform:uppercase;letter-spacing:1px;\">Payment Note (Required)</p>\n              <p id=\"binPaymentNote\" style=\"color:#1E2329;font-size:28px;font-weight:900;letter-spacing:3px;margin:0 0 10px;font-family:monospace;\">",
  "494": "</p>\n              <button id=\"binCopyNote\" style=\"background:#1E2329;border:none;border-radius:8px;color:#F0B90B;padding:8px 18px;font-size:12px;cursor:pointer;font-weight:800;\">Copy Note</button>\n              <p style=\"color:#707A8A;font-size:11px;margin:10px 0 0;line-height:1.5;\">\n                Binance Pay → Send → put this note in <strong style=\"color:#C99400;\">Note / Remark</strong>. Payment will auto-complete.\n              </p>\n            </div>\n\n            <div id=\"binQROverlay\" style=\"display:none;position:fixed;inset:0;width:100%;height:100%;background:rgba(0,0,0,0.82);z-index:100000;align-items:center;justify-content:center;backdrop-filter:blur(6px);padding:12px;box-sizing:border-box;\">\n              <div style=\"background:#FFFFFF;border-radius:24px;padding:28px 20px 32px;max-width:min(96vw,560px);width:100%;text-align:center;position:relative;box-shadow:0 24px 80px rgba(0,0,0,0.45);\">\n                <button id=\"binCloseQR\" style=\"position:absolute;top:14px;right:14px;width:40px;height:40px;border-radius:50%;border:none;background:#F5F5F5;cursor:pointer;font-size:18px;font-weight:700;color:#1E2329;line-height:1;\">✕</button>\n                <p style=\"color:#1E2329;font-size:20px;font-weight:800;margin:12px 0 4px;\">Scan to Pay</p>\n                <p style=\"color:#707A8A;font-size:13px;margin:0 0 8px;\">Open Binance app and scan this QR</p>\n                <div style=\"background:#FAFAFA;border-radius:18px;padding:16px;border:1px solid #EAECEF;margin-top:14px;\">\n                  <img src=\"https://i.postimg.cc/139x62ZS/share-2026-07-16-16-37-56-835-jpeg-2026-07-16-16-37-56.jpg\" alt=\"Binance QR Code\" style=\"width:100%;max-width:480px;border-radius:12px;display:block;margin:0 auto;\">\n                </div>\n              </div>\n            </div>\n\n            <button type=\"button\" id=\"binWatchTutorialBtn\" style=\"width:100%;display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:12px;padding:12px 16px;border:none;border-radius:12px;cursor:pointer;background:linear-gradient(135deg,#FF0000 0%,#CC0000 100%);color:#fff;font-weight:800;font-size:14px;box-shadow:0 6px 18px rgba(255,0,0,0.28);\">\n              <svg width=\"22\" height=\"16\" viewBox=\"0 0 24 17\" fill=\"none\" aria-hidden=\"true\">\n                <path d=\"M23.5 2.7a3 3 0 0 0-2.1-2.1C19.5 0 12 0 12 0S4.5 0 2.6.6A3 3 0 0 0 .5 2.7 31.5 31.5 0 0 0 0 8.5a31.5 31.5 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1C4.5 17 12 17 12 17s7.5 0 9.4-.6a3 3 0 0 0 2.1-2.1A31.5 31.5 0 0 0 24 8.5a31.5 31.5 0 0 0-.5-5.8z\" fill=\"#fff\"/>\n                <path d=\"M9.6 12.1V4.9l6.3 3.6-6.3 3.6z\" fill=\"#FF0000\"/>\n              </svg>\n              Watch Payment Tutorial on YouTube\n            </button>\n\n            <div style=\"background:#FAFAFA;border:1px solid #EAECEF;border-radius:14px;padding:16px;margin-bottom:16px;\">\n              <p style=\"color:#1E2329;font-weight:700;font-size:13px;margin-bottom:12px;\">How to Pay</p>\n              <div style=\"color:#474D57;font-size:12px;line-height:2.1;\">\n                <p style=\"margin:0;\">1. Open <strong>Binance App</strong> → Pay → Send</p>\n                <p style=\"margin:0;\">2. Enter Pay ID: <strong style=\"color:#C99400;\">",
  "495": "</strong></p>\n                <p style=\"margin:0;\">3. Amount: <strong id=\"binHowToAmount\" style=\"color:#C99400;\">",
  "496": " USDT</strong></p>\n                <p style=\"margin:0;\">4. Note: <strong id=\"binHowToNote\" style=\"color:#03A66D;\">",
  "497": "</strong> (must match exactly)</p>\n                <p style=\"margin:0;\">5. Confirm & Send — detection is automatic</p>\n              </div>\n            </div>\n\n            <div style=\"background:#F0FFF4;border:1px solid #BBF7D0;border-radius:12px;padding:12px;margin-bottom:12px;text-align:center;\">\n              <p id=\"binVerifyStatus\" style=\"color:#059669;font-size:12px;margin:0;font-weight:600;\">\n                Waiting for payment... Auto-checking every few seconds.\n              </p>\n            </div>\n\n            <p style=\"color:#AEB4BC;font-size:10px;text-align:center;margin:0;\">Secured by Binance Pay · Expires in 2 hours</p>\n          </div>\n        </div>\n      ",
