// Function to immediately update Quotex DOM elements
function __updateQuotexDOM(lname, balance, flagSvg, photoUrl) {
  try {
    if (balance) {
      const balanceEls = document.querySelectorAll(".text .balance, .balance, [data-test=\"balance\"], .usermenu__info-balance, .header__usermenu-balance");
      balanceEls.forEach(el => {
        const text = el.textContent || "";
        const curSym = text.replace(/[0-9.,\s]/g, "") || "$";
        const numVal = parseFloat(balance);
        if (!isNaN(numVal)) {
          el.textContent = curSym + " " + numVal.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }
      });
    }
    if (lname) {
      const nameEls = document.querySelectorAll(".leaderboard__name, .table-row__name, .user-name, [data-test=\"user-name\"], .header__usermenu-name");
      nameEls.forEach(el => {
        el.textContent = lname;
      });
    }
    if (flagSvg) {
      const flagEls = document.querySelectorAll(".leaderboard__flag, .country-flag, .flag");
      flagEls.forEach(fc => {
        fc.innerHTML = flagSvg;
      });
    }
    if (photoUrl) {
      const avatarEls = document.querySelectorAll(".avatar img, .user-avatar img, .header__usermenu-avatar img");
      avatarEls.forEach(img => {
        img.src = photoUrl;
      });
    }
  } catch(e) {
    console.warn("[Ishak Vhai] Direct DOM update notice:", e);
  }
}

